// The part's price, rounded up as the window shows it (customfleamarket.py,
// GetStackPurchasePrice).
static long long Mt2009PlusShopPartYang(long long yang, DWORD count, DWORD quantity)
{
	if (count == 0)
		return yang;
	return (yang * (long long) quantity + (long long) count - 1) / (long long) count;
}

