std::string StringToLower(const char* name, size_t len)
{
	// MT2009_PLUS_SHOP_SEARCH_PL_V1 (server-patches/shopsearch2): the names are CP1250, and
	// std::tolower knows A-Z only - a name beginning with a capital with a
	// diacritic (Zolc Niedzwiedzia with its dot) never matched what was typed
	// in small letters. The nine Polish capitals are lowered here too.
	static auto lower = [](char c) -> char {
		switch (static_cast<unsigned char>(c))
		{
			case 0xA5: return static_cast<char>(0xB9);
			case 0xC6: return static_cast<char>(0xE6);
			case 0xCA: return static_cast<char>(0xEA);
			case 0xA3: return static_cast<char>(0xB3);
			case 0xD1: return static_cast<char>(0xF1);
			case 0xD3: return static_cast<char>(0xF3);
			case 0x8C: return static_cast<char>(0x9C);
			case 0x8F: return static_cast<char>(0x9F);
			case 0xAF: return static_cast<char>(0xBF);
			default: return static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
		}
