	bool CShopManager::RecvShopBuyDBPacket(DWORD buyerid, DWORD ownerid,DWORD itemid, bool requester,
		DWORD quantity, DWORD remainingCount, long long remainingYang)
	{
		// MT2009_PLUS_SHOP_PART_STACK_V1 (recv buy), server-patches/shopsearch2: a part of the
		// stack sold (the Dom Towarowy). The buyer gets the part as an item of
		// its own - in the bag, or at the buyer's feet if the bag filled while
		// the purchase was on its way - and the line, on every core, keeps the
		// rest of the stack at the rest of the price.
		if (quantity != 0)
		{
			auto partShop = GetShopByOwnerID(ownerid);
			if (!partShop)
				return false;
			auto partLine = partShop->GetItem(itemid);
			if (!partLine)
				return false;

			auto partInfo = partLine->GetInfo();
			const DWORD partVnum = partInfo.vnum;
			const long long partPaid = std::max<long long>(0, (long long) partInfo.price.yang - remainingYang);
			if (auto ch = CHARACTER_MANAGER::instance().FindByPID(buyerid))
			{
				LPITEM part = ITEM_MANAGER::instance().CreateItem(partVnum, quantity);
				if (!part)
				{
					sys_err("cannot create part of item ( itemid %u , vnum %u, count %u, shop owner %u, buyer %u )",
						itemid, partVnum, quantity, ownerid, buyerid);
				}
				else
				{
					part->SetAttributes(partInfo.aAttr);
					part->SetSockets(partInfo.alSockets);
#ifdef ENABLE_CHANGELOOK_SYSTEM
					part->SetTransmutation(partInfo.dwTransmutation);
#endif
					TItemPos partPos;
					if (ch->CanTakeInventoryItem(part, &partPos))
					{
						part->AddToCharacter(ch, partPos);
						part->Save();
						ITEM_MANAGER::instance().FlushDelayedSave(part);
					}
					else
					{
						part->AddToGround(ch->GetMapIndex(), ch->GetXYZ());
						part->StartDestroyEvent();
						part->SetOwnership(ch, 300);
						ch->ChatPacket(CHAT_TYPE_INFO, "Ekwipunek jest pelny - kupiona czesc stosu lezy pod Twoimi stopami.");
					}
				}
				ch->ChatPacket(CHAT_TYPE_COMMAND, "FleaMarketStackUpdate %u %u %u %lld 0",
					ownerid, itemid, remainingCount, remainingYang);
			}

			partInfo.count = remainingCount;
			partInfo.price.yang = remainingYang;
			partLine->SetInfo(partInfo);
			for (auto guest : partShop->GetGuests())
				if (auto guestCh = CHARACTER_MANAGER::instance().FindByPID(guest))
					SendShopOpenClientPacket(guestCh, partShop.get());
			partShop->RefreshToOwner();

			auto partOwnerCh = CHARACTER_MANAGER::instance().FindByPID(ownerid);
			if (partOwnerCh)
				NotifyOwnerItemSold(partOwnerCh, partVnum, quantity, partPaid);
			// A bot's line sold in part stays on its counter (playerbot_offline::NoteSold).
			playerbot_offline::NoteSold(partOwnerCh ? ownerid : 0, itemid, partVnum, quantity, partPaid, true);
			playerbot_offline::Complete(buyerid, playerbot_offline::Buy, itemid);
			return true;
		}

